/** The CLI usage text. */
export const CLI_USAGE = "loom - schema-driven systems-engineering model\n\nUsage: loom <command> [options]   (every command takes --json to print the result envelope)\n\n  init [--force]                         Scaffold .loom with model.json, loom.json, state.json and .gitignore at a\n                                         repository root, never staging or committing them.\n  check [--model <path>] [--out <dir>]   Check one model in order, its ownership and configuration, its validity, its\n                                         comparison with the trusted accepted baseline and its installed outputs and\n                                         manifest, or with --out a directory of projections, without writing.\n  check --all [--boundary <dir>]         Check every descriptor under the boundary, the global disjointness of their\n                                         claims and whether the walk covered the whole boundary.\n  write [--out <dir>] [--draft]          Install every artifact the workspace's projection profile enables, with the\n                                         readiness, coverage and evidence views evaluated under the verified inputs, or\n                                         with --out write every projection into a directory.\n  docs [--out <dir>] [--draft]           Install the documentation bundle, every enabled artifact with the readiness,\n                                         coverage and evidence views evaluated, exactly as write installs it.\n  docs --check                           Check the README, the Docs documents and the package source comments for broken\n                                         links, anchors and record references, narrated history and hand-authored copies\n                                         of generated registers, and inside a workspace the installed views and the\n                                         interfaces the accepted baseline holds.\n  docs --check --self                    Run the documentation checks over this Loom installation's own repository and\n                                         add its release wording: no requirement, task or phase label, release-iteration\n                                         label or product-generation term in a document, comment or JSON description.\n  owner [<path>]                         Name the model and component that claim a path by whole segments, or report the\n                                         path as unclaimed, claimed twice or unresolved.\n  migrate [--model <path>] [--to <file>] Migrate a model document to the current model format, writing the result only\n                                         to a new file named with --to and never replacing its source.\n  baseline create --id <id> --acceptance <id> [--predecessor <id>] [--frozen]\n                                         Record a baseline of the workspace model at its current revision, accepted by a\n                                         named acceptance record and optionally frozen.\n  accept --id <id> --authority <alias> [--subject baseline|change] [--baseline <id>] [--scope kind:id,...] [--classes ...]\n                                         Record an acceptance of the current model revision, as a baseline or a change,\n                                         by a named authority under the workspace policy, optionally signed.\n  mutate --patch <file> --expected <revision> [--ack id,...] [--dry-run]\n                                         Apply one patch or an atomic batch to a model, inline as a pure calculation or\n                                         to the workspace model, which persists only onto the expected revision so two\n                                         writers on one base cannot both succeed, while a dry run previews without\n                                         writing.\n  qualify [--self] [--profile p,...] [--checks id,...] [--fixtures <file>] [--store] [--metrics [--compare <metrics.json>]] [--key-id <id> --key-env <var>]\n                                         Run the native-tool checks of the profiles the workspace enables, or of named\n                                         profiles or checks, against artifacts rendered from the model, judge their\n                                         evidence under the trusted policy and optionally store and sign it, while\n                                         --self runs every check against Loom's own fixtures.\n  evidence list | evidence show <id>     List the stored evidence with each record's trust under the trusted policy, or\n                                         show one record.\n  coverage --check [--register <file>] [--results <tap,...>] [--run <run.json>] | coverage --list-cases\n                                         Check the capability register qualification/capabilities.json, every code\n                                         symbol, contract pointer and verification case resolving and a case counting\n                                         only on a supplied passing result, or list the declared verification cases.\n  --self-test                            Run Loom's self-test, which qualifies Loom's own engine and never an adopting\n                                         system: the MCP tool runs the engine battery, and the command adds the drift\n                                         gate, the release wording and every profile check against Loom's fixtures.\n  describe [--sections a,b] [--profile <id>]\n                                         Describe what this build supports: record kinds, patch operations, finding\n                                         codes, comparison rules, projection targets, profiles with their proof limits,\n                                         tools, examples and unavailable features.\n  context --kind component|record|claim|task --id <id> [--record-kind <kind>] [--max-records n] [--max-bytes n] [--continuation <token>]\n                                         Retrieve the required context of a component, record, claim or task within a\n                                         declared budget, nearest first, with sources, owners, baseline status,\n                                         constraints, decisions and evidence, record text coming back as data and never\n                                         as an instruction.\n  readiness --class <class> [--mode component|slice] [--components a,b] [--requirements r,...] | readiness --task <file>\n                                         Evaluate whether a task is ready, blocked or unresolved, with the exact missing\n                                         prerequisites, permitted substitutes, allowed next work and its work package.\n  plan --patch <file> [--base <revision>] [--ack id,...]\n                                         Preview a change against a base revision without persisting it: the delta,\n                                         compatibility by dimension, affected consumers with dependency paths,\n                                         invalidated evidence, repair alternatives, obligations and whether policy\n                                         requires acceptance.\n\nCommon options: --model <path> selects a document (the governing workspace still applies), --boundary <dir>, --trusted-ref <ref>, --as-of <date>.\nExit status: 0 ok, 1 refusal or error finding, 2 usage error.";
